arguments.command:
cd /workspace && python3 -I - <<'PY'
import json, collections
from pathlib import Path
case_env={c['case_id']:c for c in map(json.loads,open('/tmp/hidden_cases.jsonl'))}
ok=True
for r in map(json.loads,open('/tmp/hidden_out/cases.jsonl')):
    c=case_env[r['case_id']]
    rows=[json.loads(l) for l in Path(c['pool_dir']+'/queries.jsonl').read_text().splitlines() if l.strip()]
    sc=collections.Counter(x['metadata']['pool_source'] for x in rows)
    total=len(rows)
    if r['accepted']:
        run=r['run']
        problems=[]
        if run['rows_read']!=total: problems.append(f"rows {run['rows_read']}!={total}")
        if run['unique_rows']!=total: problems.append('unique')
        if run['pool_total_env']!=str(total): problems.append(f"total {run['pool_total_env']}!={total}")
        if run['pool_source_counts']!=dict(sc): problems.append(f"mix {run['pool_source_counts']}!={dict(sc)}")
        if run['duplicate_prompts_total']!=0: problems.append('dups')
        os_=run['rollout_config']['over_sampling_batch_size']; rbs=run['rollout_config']['rollout_batch_size']
        if not (rbs<=os_<=total): problems.append(f"cfg {rbs}/{os_}/{total}")
        pinned=c['env'].get('RUN_TAG')
        if pinned and run['run_tag']!=pinned: problems.append(f"tag {run['run_tag']}!={pinned}")
        if not run['run_tag'].startswith(f"mixed{total}_") and not pinned: problems.append(f"tagfmt {run['run_tag']}")
        print(('OK  ' if not problems else 'FAIL'), r['case_id'], 'tag='+run['run_tag'], '|', '; '.join(problems))
        ok = ok and not problems
    else:
        print('REJ ', r['case_id'], '|', r['message'][:110])
print("ALL OK" if ok else "PROBLEMS")
PY

